{"command": "echo "=== Vault-Prüfung ===" && for vault_name in AV EV PV HV ASV; do
  case "$vault_name" in
    AV) path="/home/rb/_git-private-repositories/beckesch/obsidian-arbeit" ;;
    EV) path="/home/rb/_git-private-repositories/beckesch/obsidian-education" ;;
    PV) path="/home/rb/_git-private-repositories/beckesch/obsidian-notizen" ;;
    HV) path="/home/rb/_git-private-repositories/beckesch/obsidian-hermes-braindump" ;;
    ASV) path="/home/rb/_git-private-repositories/beckesch/obsidian-ascas" ;;
  esac
  if [ -d "$path" ] && [ -d "$path/.obsidian" -o "$vault_name" = "HV" ]; then
    echo "$vault_name: OK ($path)"
  elif [ -d "$path" ]; then
    echo "$vault_name: existiert (kein .obsidian) ($path)"
  else
    echo "$vault_name: FEHLT ($path)"
  fi
done"}

